data.typescript:
export interface Address {
  city: string;
}

export interface User {
  id: number;
  name: string;
  address: Address;
  tags: string[];
}

data.code:
export function total(items: { price: number; qty: number }[]): number {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}
